import java.util.HashMap;
import java.util.Map;

class FileSystem {
    private Map<String, Integer> values;

    public FileSystem() {
        values = new HashMap<>();
        values.put("", 0);
    }

    public boolean createPath(String path, int value) {
        if (values.containsKey(path)) {
            return false;
        }
        int split = path.lastIndexOf('/');
        String parent = path.substring(0, split);
        if (!values.containsKey(parent)) {
            return false;
        }
        values.put(path, value);
        return true;
    }

    public int get(String path) {
        return values.getOrDefault(path, -1);
    }
}

import java.util.HashMap;
import java.util.Map;

class FileSystem {
    private static class Node {
        Map<String, Node> children = new HashMap<>();
        int value = -1;
    }

    private Node root;

    public FileSystem() {
        root = new Node();
    }

    public boolean createPath(String path, int value) {
        String[] parts = path.split("/");
        Node current = root;
        for (int i = 1; i < parts.length - 1; i++) {
            current = current.children.get(parts[i]);
            if (current == null) {
                return false;
            }
        }
        String leaf = parts[parts.length - 1];
        if (current.children.containsKey(leaf)) {
            return false;
        }
        Node child = new Node();
        child.value = value;
        current.children.put(leaf, child);
        return true;
    }

    public int get(String path) {
        String[] parts = path.split("/");
        Node current = root;
        for (int i = 1; i < parts.length; i++) {
            current = current.children.get(parts[i]);
            if (current == null) {
                return -1;
            }
        }
        return current.value;
    }
}

import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

class FileSystem {
    private Map<String, Integer>[] children;
    private int[] nodeValues;
    private int nextId;

    public FileSystem() {
        children = new HashMap[100001];
        nodeValues = new int[100001];
        Arrays.fill(nodeValues, -1);
        children[0] = new HashMap<>();
        nextId = 1;
    }

    public boolean createPath(String path, int value) {
        String[] parts = path.split("/");
        int node = 0;
        for (int i = 1; i < parts.length - 1; i++) {
            Integer child = children[node].get(parts[i]);
            if (child == null) {
                return false;
            }
            node = child;
        }
        String leaf = parts[parts.length - 1];
        if (children[node].containsKey(leaf)) {
            return false;
        }
        int newNode = nextId++;
        children[newNode] = new HashMap<>();
        nodeValues[newNode] = value;
        children[node].put(leaf, newNode);
        return true;
    }

    public int get(String path) {
        String[] parts = path.split("/");
        int node = 0;
        for (int i = 1; i < parts.length; i++) {
            Integer child = children[node].get(parts[i]);
            if (child == null) {
                return -1;
            }
            node = child;
        }
        return nodeValues[node];
    }
}

import java.util.ArrayList;
