class FileSystem {
    private Map<String, Integer> idByPath;
    private List<Integer> values;

    public FileSystem() {
        idByPath = new HashMap<>();
        values = new ArrayList<>();
        idByPath.put("", 0);
        values.add(-1);
    }

    public boolean createPath(String path, int value) {
        if (idByPath.containsKey(path)) {
            return false;
        }
        int split = path.lastIndexOf('/');
        String parent = path.substring(0, split);
        if (!idByPath.containsKey(parent)) {
            return false;
        }
        idByPath.put(path, values.size());
        values.add(value);
        return true;
    }

    public int get(String path) {
        Integer id = idByPath.get(path);
        if (id == null) {
            return -1;
        }
        return values.get(id);
    }
}

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

class FileSystem {
    private Map<String, Integer> values;
    private Map<String, Set<String>> childrenByParent;

    public FileSystem() {
        values = new HashMap<>();
        childrenByParent = new HashMap<>();
        values.put("", 0);
        childrenByParent.put("", new HashSet<>());
    }

    public boolean createPath(String path, int value) {
        if (values.containsKey(path)) {
            return false;
        }
        int split = path.lastIndexOf('/');
        String parent = path.substring(0, split);
        String leaf = path.substring(split + 1);
        if (!childrenByParent.containsKey(parent)) {
            return false;
        }
        childrenByParent.get(parent).add(leaf);
        childrenByParent.put(path, new HashSet<>());
        values.put(path, value);
        return true;
    }

    public int get(String path) {
        return values.getOrDefault(path, -1);
    }
}
